def _edge_bar_pair(grid, background):
    """Find matching equal-length bars on opposite edges."""
    h, w = len(grid), len(grid[0])
    candidates = []
    for axis in (0, 1):  # 0: top/bottom; 1: left/right
        first = grid[0] if axis == 0 else [grid[r][0] for r in range(h)]
        last = grid[-1] if axis == 0 else [grid[r][-1] for r in range(h)]
        for color_a, a, b in _runs(first, background):
            for color_b, c, d in _runs(last, background):
                if color_a == color_b and b - a == d - c:
                    candidates.append((axis, a, b, c, d, color_a))
    return candidates[0] if candidates else None


def transform(grid):
    """Extend edge-aligned clues toward their edge and across the paired bar."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    pair = _edge_bar_pair(grid, background)
    if pair is None:
        return out

    axis, a, b, c, d, bar_color = pair
    if axis == 0:
        bar_cells = {(0, col) for col in range(a, b)} | {
            (h - 1, col) for col in range(c, d)
        }
    else:
        bar_cells = {(row, 0) for row in range(a, b)} | {
            (row, w - 1) for row in range(c, d)
        }

    clues = [
        (r, col, grid[r][col])
        for r in range(h) for col in range(w)
        if grid[r][col] not in (background, bar_color)
    ]

    for r, col, color in clues:
        position = col if axis == 0 else r
        if a <= position < b:
            offset = position - a
            if axis == 0:
                local_ray = [(rr, col) for rr in range(1, r + 1)]
                paired_pos = c + offset
                paired_ray = [(rr, paired_pos) for rr in range(h)]
            else:
                local_ray = [(r, cc) for cc in range(1, col + 1)]
                paired_pos = c + offset
                paired_ray = [(paired_pos, cc) for cc in range(w)]
        elif c <= position < d:
            offset = position - c
            if axis == 0:
                local_ray = [(rr, col) for rr in range(r, h - 1)]
                paired_pos = a + offset
                paired_ray = [(rr, paired_pos) for rr in range(h)]
            else:
                local_ray = [(r, cc) for cc in range(col, w - 1)]
                paired_pos = a + offset
                paired_ray = [(paired_pos, cc) for cc in range(w)]
        else:
            continue

        for rr, cc in local_ray + paired_ray:
            if (rr, cc) not in bar_cells:
                out[rr][cc] = color

    # Clue cells become marker color 4 after all strokes are drawn.
